from __future__ import annotations

import csv
import json
from decimal import Decimal


DISPOSAL_TIMESTAMP = "2023-07-18 03:17:00"


def parse_decimal(raw: str) -> Decimal:
    return Decimal(raw.replace(",", "."))


def answer() -> int:
    products_by_id: dict[str, dict[str, str]] = {}
    products_by_ean: dict[str, dict[str, str]] = {}

    with open("/app/dataset/product_catalog.csv", newline="") as f:
        for row in csv.DictReader(f):
            products_by_id[row["product_id"]] = row
            products_by_ean[row["ean_code"]] = row

    revenue = Decimal("0")

    with open("/app/dataset/warehouse_dispatches.csv", newline="") as f:
        for row in csv.DictReader(f):
            if row["timestamp"] == DISPOSAL_TIMESTAMP:
                # This exact batch aligns with the only severe cold-chain breach
                # and is the only dispatch cluster that clearly represents spoilage.
                continue

            product = products_by_id.get(row["product_id"]) or products_by_ean[row["product_id"]]
            revenue += parse_decimal(product["unit_price"]) * int(row["quantity"])

    return int(revenue)


if __name__ == "__main__":
    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)
